/* =========================================================
   CASA PLANNER — Cloudflare Worker (archivo único)
   Contiene: servidor de la app (index.html embebido) + API
   de registro / login / datos, guardados en Workers KV.

   BINDINGS NECESARIOS (Settings -> Variables and Bindings):
     - KV Namespace  -> nombre de variable: USERS    (namespace: casa-planner-users)
     - KV Namespace  -> nombre de variable: APPDATA  (namespace: casa-planner-data)
     - Secret        -> nombre de variable: JWT_SECRET (cadena aleatoria larga)
   ========================================================= */

const enc = new TextEncoder();

function toB64Url(bytes) {
  let str = '';
  bytes.forEach((b) => (str += String.fromCharCode(b)));
  return btoa(str).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}
function fromB64Url(str) {
  str = str.replace(/-/g, '+').replace(/_/g, '/');
  while (str.length % 4) str += '=';
  const bin = atob(str);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return bytes;
}

// ---- Hash de contraseñas (PBKDF2-SHA256) ----
async function hashPassword(password) {
  const salt = crypto.getRandomValues(new Uint8Array(16));
  const keyMaterial = await crypto.subtle.importKey('raw', enc.encode(password), 'PBKDF2', false, ['deriveBits']);
  const iterations = 100000;
  const bits = await crypto.subtle.deriveBits(
    { name: 'PBKDF2', salt, iterations, hash: 'SHA-256' },
    keyMaterial,
    256
  );
  return `pbkdf2$${iterations}$${toB64Url(salt)}$${toB64Url(new Uint8Array(bits))}`;
}

async function verifyPassword(password, stored) {
  const parts = (stored || '').split('$');
  if (parts.length !== 4 || parts[0] !== 'pbkdf2') return false;
  const iterations = parseInt(parts[1], 10);
  const salt = fromB64Url(parts[2]);
  const expected = parts[3];
  const keyMaterial = await crypto.subtle.importKey('raw', enc.encode(password), 'PBKDF2', false, ['deriveBits']);
  const bits = await crypto.subtle.deriveBits(
    { name: 'PBKDF2', salt, iterations, hash: 'SHA-256' },
    keyMaterial,
    256
  );
  return toB64Url(new Uint8Array(bits)) === expected;
}

// ---- Tokens de sesión firmados (HMAC-SHA256) ----
async function getHmacKey(secret) {
  return crypto.subtle.importKey('raw', enc.encode(secret), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign', 'verify']);
}

const SESSION_DAYS = 30;

async function createToken(username, secret) {
  const payload = { u: username, exp: Date.now() + SESSION_DAYS * 24 * 60 * 60 * 1000 };
  const payloadB64 = toB64Url(enc.encode(JSON.stringify(payload)));
  const key = await getHmacKey(secret);
  const sig = await crypto.subtle.sign('HMAC', key, enc.encode(payloadB64));
  const sigB64 = toB64Url(new Uint8Array(sig));
  return `${payloadB64}.${sigB64}`;
}

async function verifyToken(token, secret) {
  if (!token) return null;
  const parts = token.split('.');
  if (parts.length !== 2) return null;
  const [payloadB64, sigB64] = parts;
  const key = await getHmacKey(secret);
  const valid = await crypto.subtle.verify('HMAC', key, fromB64Url(sigB64), enc.encode(payloadB64));
  if (!valid) return null;
  try {
    const payload = JSON.parse(new TextDecoder().decode(fromB64Url(payloadB64)));
    if (!payload.exp || payload.exp < Date.now()) return null;
    return payload.u;
  } catch (e) {
    return null;
  }
}

function getBearerToken(request) {
  const h = request.headers.get('Authorization') || '';
  const m = h.match(/^Bearer (.+)$/);
  return m ? m[1] : null;
}

function json(obj, status) {
  return new Response(JSON.stringify(obj), {
    status: status || 200,
    headers: { 'Content-Type': 'application/json; charset=utf-8' },
  });
}

// ---- El index.html va embebido en Base64 más abajo (HTML_B64_PARTS) ----
const HTML_B64 = "";

function decodeHtml() {
  const bin = atob(HTML_B64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return new TextDecoder('utf-8').decode(bytes);
}

async function handleRegister(request, env) {
  let body;
  try {
    body = await request.json();
  } catch (e) {
    return json({ error: 'JSON inválido' }, 400);
  }
  const username = (body.username || '').trim().toLowerCase();
  const password = body.password || '';

  if (!/^[a-z0-9_.-]{3,32}$/.test(username)) {
    return json({ error: 'usuario inválido' }, 400);
  }
  if (password.length < 6) {
    return json({ error: 'contraseña demasiado corta' }, 400);
  }

  const existing = await env.USERS.get(`user:${username}`);
  if (existing) {
    return json({ error: 'exists' }, 409);
  }

  const passwordHash = await hashPassword(password);
  await env.USERS.put(`user:${username}`, JSON.stringify({ passwordHash, createdAt: new Date().toISOString() }));

  const token = await createToken(username, env.JWT_SECRET);
  return json({ token });
}

async function handleLogin(request, env) {
  let body;
  try {
    body = await request.json();
  } catch (e) {
    return json({ error: 'JSON inválido' }, 400);
  }
  const username = (body.username || '').trim().toLowerCase();
  const password = body.password || '';

  const raw = await env.USERS.get(`user:${username}`);
  if (!raw) {
    return json({ error: 'credenciales inválidas' }, 401);
  }
  const user = JSON.parse(raw);
  const ok = await verifyPassword(password, user.passwordHash);
  if (!ok) {
    return json({ error: 'credenciales inválidas' }, 401);
  }

  const token = await createToken(username, env.JWT_SECRET);
  return json({ token });
}

async function authenticate(request, env) {
  const token = getBearerToken(request);
  return await verifyToken(token, env.JWT_SECRET);
}

async function handleGetData(request, env) {
  const username = await authenticate(request, env);
  if (!username) return json({ error: 'no autorizado' }, 401);
  const raw = await env.APPDATA.get(`data:${username}`);
  const data = raw ? JSON.parse(raw) : null;
  return json({ data });
}

async function handlePutData(request, env) {
  const username = await authenticate(request, env);
  if (!username) return json({ error: 'no autorizado' }, 401);
  let body;
  try {
    body = await request.json();
  } catch (e) {
    return json({ error: 'JSON inválido' }, 400);
  }
  if (!body || typeof body.data !== 'object') {
    return json({ error: 'falta "data"' }, 400);
  }
  await env.APPDATA.put(`data:${username}`, JSON.stringify(body.data));
  return json({ ok: true });
}

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    const path = url.pathname;
    const method = request.method;

    try {
      if (path === '/api/register' && method === 'POST') return await handleRegister(request, env);
      if (path === '/api/login' && method === 'POST') return await handleLogin(request, env);
      if (path === '/api/data' && method === 'GET') return await handleGetData(request, env);
      if (path === '/api/data' && method === 'PUT') return await handlePutData(request, env);
      if (path.startsWith('/api/')) return json({ error: 'no encontrado' }, 404);

      // Cualquier otra ruta -> servir la app (index.html embebido)
      return new Response(decodeHtml(), {
        headers: { 'Content-Type': 'text/html; charset=utf-8' },
      });
    } catch (err) {
      return json({ error: 'error interno', detail: String(err) }, 500);
    }
  },
};
